CREATE TABLE IF NOT EXISTS migrations(version INTEGER PRIMARY KEY);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT UNIQUE NOT NULL,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,display TEXT NOT NULL,bio TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'online',custom_status TEXT NOT NULL DEFAULT '',created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS spaces(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',owner TEXT NOT NULL REFERENCES users(id));
CREATE TABLE IF NOT EXISTS members(space_id TEXT REFERENCES spaces(id),user_id TEXT REFERENCES users(id),role TEXT NOT NULL DEFAULT 'member',PRIMARY KEY(space_id,user_id));
CREATE TABLE IF NOT EXISTS channels(id TEXT PRIMARY KEY,space_id TEXT REFERENCES spaces(id),name TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('text','voice')),private INTEGER NOT NULL DEFAULT 0,position INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS channel_members(channel_id TEXT REFERENCES channels(id),user_id TEXT REFERENCES users(id),PRIMARY KEY(channel_id,user_id));
CREATE TABLE IF NOT EXISTS invites(code TEXT PRIMARY KEY,space_id TEXT REFERENCES spaces(id),expires INTEGER NOT NULL,max_uses INTEGER NOT NULL,uses INTEGER NOT NULL DEFAULT 0,revoked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS messages(seq INTEGER PRIMARY KEY AUTOINCREMENT,id TEXT UNIQUE NOT NULL,channel_id TEXT REFERENCES channels(id),user_id TEXT REFERENCES users(id),body TEXT NOT NULL,created INTEGER NOT NULL,edited INTEGER,reply_id TEXT REFERENCES messages(id),pinned INTEGER NOT NULL DEFAULT 0,UNIQUE(user_id,id));
CREATE INDEX IF NOT EXISTS message_channel ON messages(channel_id,seq);
CREATE TABLE IF NOT EXISTS reactions(message_id TEXT REFERENCES messages(id) ON DELETE CASCADE,user_id TEXT REFERENCES users(id),emoji TEXT NOT NULL,PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS relationships(sender TEXT REFERENCES users(id),recipient TEXT REFERENCES users(id),state TEXT NOT NULL CHECK(state IN ('pending','accepted','blocked')),PRIMARY KEY(sender,recipient));
CREATE TABLE IF NOT EXISTS reads(user_id TEXT REFERENCES users(id),channel_id TEXT REFERENCES channels(id),seq INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(user_id,channel_id));
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,space_id TEXT,actor TEXT,action TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bans(space_id TEXT REFERENCES spaces(id),user_id TEXT REFERENCES users(id),PRIMARY KEY(space_id,user_id));
CREATE TABLE IF NOT EXISTS direct_conversations(space_id TEXT PRIMARY KEY REFERENCES spaces(id),participant_key TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS files(id TEXT PRIMARY KEY,channel_id TEXT NOT NULL REFERENCES channels(id),user_id TEXT NOT NULL REFERENCES users(id),name TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,content BLOB NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,reporter TEXT REFERENCES users(id),target TEXT REFERENCES users(id),space_id TEXT REFERENCES spaces(id),reason TEXT NOT NULL,created INTEGER NOT NULL);
INSERT OR IGNORE INTO migrations VALUES(1);
